SELECT t.ticker AS ticker, t.time AS time, t.Close AS Close FROM tav2_bq.ticker t WHERE t.ticker IN ("AAA","APH","ASM","BCG","CEO","CII","CSV","CTD","DLG","DPM","DRH","GEX","HAH","HBC","HHV","HPX","HQC","HSG","IDI","IJC","ITA","JVC","KBC","KDC","KHG","KSB","LCG","LDG","LPB","MBB","NBB","NKG","NLG","NVB","PAN","PC1","POW","PVC","PVD","PVS","PVT","PVX","QCG","REE","SCR","SHB","SHS","SSI","STB","TCH","TDH","TNG","VCI","VND","VSH","VNINDEX") AND t.time>="2009-06-01" ORDER BY t.ticker, t.time